import django.core.validators
from django.db import migrations, models


def midtstilt_utsnitt(apps, schema_editor):
    """Eksisterende bilder: dagens bilde blir originalen, med et midtstilt 16:9-utsnitt.

    Selve de beskårne filene lages med «python manage.py lag_forsidebilder».
    Regnestykket står her (ikke importert fra models.py), så migrasjonen virker
    selv om modellen endres senere.
    """
    Forsidebilde = apps.get_model("profil", "Forsidebilde")
    for bilde in Forsidebilde.objects.all():
        bredde, hoyde = bilde.bredde, bilde.hoyde
        bilde.original_bredde, bilde.original_hoyde = bredde, hoyde
        if bredde and hoyde:
            b = min(bredde, hoyde * 16 / 9)
            h = b * 9 / 16
            bilde.utsnitt_x = (bredde - b) / 2 / bredde * 100
            bilde.utsnitt_y = (hoyde - h) / 2 / hoyde * 100
            bilde.utsnitt_bredde = b / bredde * 100
            bilde.utsnitt_hoyde = h / hoyde * 100
        bilde.save()


